SELECT to_external AS "name", COUNT(*) AS "count"
  FROM analysis_relation
 WHERE revision_id = #{revisionId}
   AND relation_type = #{relationType}
   AND to_id IS NULL
   AND to_external IS NOT NULL
 GROUP BY to_external
 ORDER BY COUNT(*) DESC, to_external
 LIMIT #{limit}

SELECT COUNT(*)
  FROM analysis_relation
 WHERE revision_id = #{revisionId}
   AND relation_type = #{relationType}
   AND to_id IS NULL
   AND to_external IS NOT NULL
